@dataclass(frozen=True)
class RollbackJournalEntry:
    path: str
    before_hash: str
    after_hash: str = ''
    backup_path: str = ''

class ProjectEditRollbackJournal:
    def __init__(self, project_root: Path, journal_root: Path):
        self.project_root = project_root.resolve()
        self.journal_root = journal_root
        self.entries: dict[Path, RollbackJournalEntry] = {}

    def snapshot_file(self, path: Path) -> RollbackJournalEntry:
        target = path.resolve()
        if self.project_root not in target.parents and target != self.project_root:
            raise ValueError('path_outside_project')
        before_hash = _sha256(target) if target.exists() else ''
        backup_path = self._backup_path_for(target)
        if target.exists():
            backup_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup_path)
        entry = RollbackJournalEntry(str(target), before_hash, backup_path=str(backup_path))
        self.entries[target] = entry
        self._write_manifest()
        return entry

    def record_change(self, path: Path) -> None:
        target = path.resolve()
        entry = self.entries[target]
        self.entries[target] = replace(entry, after_hash=_sha256(target) if target.exists() else '')
        self._write_manifest()

    def rollback(self) -> dict[str, Any]:
        restored = []
        for target, entry in reversed(self.entries.items()):
            if entry.backup_path and Path(entry.backup_path).exists():
                shutil.copy2(entry.backup_path, target)
            elif target.exists():
                target.unlink()
            restored.append(str(target))
        return {'status': 'rolled_back', 'restored': restored}

